public class Main {
    static int removeEmpty(java.util.ArrayList<String> xs) {
        int removed = 0;
        java.util.Iterator<String> it = xs.iterator();
        while (it.hasNext()) {
            if (it.next().isEmpty()) { it.remove(); removed++; }
        }
        return removed;
    }
    public static void main(String[] args) {
        java.util.ArrayList<String> xs = new java.util.ArrayList<>(java.util.List.of("", "a"));
        System.out.println(removeEmpty(xs));
    }
}

